// Interface lubrication element. Unified problems
#ifndef OOMPH_LOWER_INTERFACE_LUBRICATION_HEADER
#define OOMPH_LOWER_INTERFACE_LUBRICATION_HEADER

// Config header generated by autoconfig
#ifdef HAVE_CONFIG_H
#include <oomph-lib-config.h>
#endif

// oomph-lib headers
#include "../fluid_interface/specific_node_update_interface_elements.h"

namespace oomph {
//==================================================================
/// Generic vapour lubrication equations implemented
/// independently of the dimension and then specialised using
/// the generic mechanisms introduce in the FluidInterfaceElements
//=================================================================
class LowerInterfaceLubricationElement : public FluidInterfaceElement {
private:
  /// Pointer to ratio of vapour viscosity to liquid viscosity
  double *Vapour_Viscosity_Ratio_pt;

  /// Pointer to Dim-less Hamaker number
  double *Hamaker_pt;

  /// Pointer to Dim-less Mean Free Path
  double *Mean_Free_Path_pt;

  /// Pointer to GKE factor Delta Tau P function
  void (*GKE_Tau_P_fct_pt)(const double &Kn, double &result);

  /// Pointer to GKE factor Delta Tau C function
  void (*GKE_Tau_C_fct_pt)(const double &Kn, double &result);

protected:
  /// Index at which the Arc length is stored at the
  /// nodes
  Vector<unsigned> Al_index;

  /// Default value of the physical constants
  static double Default_Physical_Constant_Value;

  bool under_drop_flag;

  /// Get the arc length
  double interpolated_Al(const Vector<double> &s);

  /// Overload the Helper function to calculate the residuals and
  /// jacobian entries. This particular function ensures that the
  /// additional entries are calculated inside the integration loop
  void add_additional_residual_contributions_interface(
      Vector<double> &residuals, DenseMatrix<double> &jacobian,
      const unsigned &flag, const Shape &psif, const DShape &dpsifds,
      const DShape &dpsifdS, const DShape &dpsifdS_div, const Vector<double> &s,
      const Vector<double> &interpolated_x,
      const Vector<double> &interpolated_n, const double &W, const double &J);

  /// Function to calculate GKE Tau P factor
  void get_GKE_Tau_P(const double &Kn, double &result) {
    // If the function pointer is zero return 1
    if (GKE_Tau_P_fct_pt == 0) {
      result = 1.0;
    }
    // Otherwise call the function
    else {
      (*GKE_Tau_P_fct_pt)(Kn, result);
    }
  }

  /// Function to calculate GKE Tau C factor
  void get_GKE_Tau_C(const double &Kn, double &result) {
    // If the function pointer is zero return 1
    if (GKE_Tau_C_fct_pt == 0) {
      result = 1.0;
    }
    // Otherwise call the function
    else {
      (*GKE_Tau_C_fct_pt)(Kn, result);
    }
  }

  /// Function to calculate impact surface
  virtual void get_upper_surface(const unsigned &intpt, Vector<double> &x_out,
                                 Vector<double> &u_out, double &pv_out,
                                 Vector<double> &grad_pv_out) {
    // Return 0. Virtual to overwrite for the external element
    x_out[0] = 0.0;
    x_out[1] = 0.0;
    u_out[0] = 0.0;
    u_out[1] = 0.0;
    pv_out = 0.0;
    grad_pv_out[0] = 0.0;
    grad_pv_out[1] = 0.0;
  }

  /// Add the element's contribution to its residuals vector,
  /// jacobian matrix and mass matrix
  void fill_in_contribution_to_jacobian_and_mass_matrix(
      Vector<double> &residuals, DenseMatrix<double> &jacobian,
      DenseMatrix<double> &mass_matrix) {
    // Add the contribution to the jacobian
    this->fill_in_contribution_to_jacobian(residuals, jacobian);
    // No mass matrix terms, but should probably do kinematic bit here
  }

public:
  /// Constructor that passes the bulk element and face index down
  /// to the underlying
  LowerInterfaceLubricationElement() : FluidInterfaceElement() {
    // Initialise the values
    Vapour_Viscosity_Ratio_pt = &Default_Physical_Constant_Value;
    Hamaker_pt = &Default_Physical_Constant_Value;
    Mean_Free_Path_pt = &Default_Physical_Constant_Value;

    GKE_Tau_P_fct_pt = 0;
    GKE_Tau_C_fct_pt = 0;
    under_drop_flag = true;
  }

  /// Destructor should not delete anything
  ~LowerInterfaceLubricationElement() {}

  // Access function for the GKE Tau P factor pointer
  void (*&gke_Tau_P_fct_pt())(const double &Kn, double &result) {
    return GKE_Tau_P_fct_pt;
  }

  // Access function for the GKE Tau C factor pointer
  void (*&gke_Tau_C_fct_pt())(const double &Kn, double &result) {
    return GKE_Tau_C_fct_pt;
  }

  // Set the al_index
  inline void set_al_index(const Vector<unsigned> &al_index) {
    this->Al_index = al_index;
  }

  bool under_drop() const { return under_drop_flag; }

  void set_under_drop(bool under_drop_in) { under_drop_flag = under_drop_in; }

  /// Return the vapour viscosity ratio
  double vapour_viscosity_ratio() { return *Vapour_Viscosity_Ratio_pt; }

  /// Return the vapour viscosity ratio
  double vapour_viscosity_ratio() const { return *Vapour_Viscosity_Ratio_pt; }

  /// Return the Dim-less Hamaker number
  double hamaker() { return *Hamaker_pt; }

  /// Return the Dim-less Hamaker number
  double hamaker() const { return *Hamaker_pt; }

  /// Return the Dim-less Mean Free Path
  double mean_free_path() { return *Mean_Free_Path_pt; }

  /// Access function for pointer to the vapour viscosity ratio
  double *&vapour_viscosity_ratio_pt() { return Vapour_Viscosity_Ratio_pt; }

  /// Access function for pointer to the Dim-less Hamaker number
  double *&hamaker_pt() { return Hamaker_pt; }

  /// Access function for pointer to the Dim-less mean free path
  double *&mean_free_path_pt() { return Mean_Free_Path_pt; }

  // fix the arc length
  void fix_arc_length(const unsigned &al_dof, const double &al_value) {
    this->node_pt(al_dof)->pin(this->Al_index[al_dof]);
    this->node_pt(al_dof)->set_value(this->Al_index[al_dof], al_value);
  }

  void to_upper_surface(const Vector<double> &s, Vector<double> &x_out,
                        Vector<double> &n_out, Vector<double> &u_out, Vector<double> &dx_dt_out) const {

    // Return x,u,n
    unsigned n_node = this->nnode();
    const unsigned n_dim = this->node_pt(0)->ndim();
    Vector<unsigned> u_index = this->U_index_interface;

    // Find out the number of surface coordinates
    const unsigned el_dim = this->dim();
    // We have el_dim local surface coordinates
    DShape dpsifds(n_node, el_dim);
    Shape psif(n_node);
    this->dshape_local(s, psif, dpsifds);

    for (unsigned l = 0; l < n_node; l++) {
      const double psi = psif(l);
      const double r_ = this->nodal_position(l, 0);
      const double h_ = this->nodal_position(l, 1);
      x_out[0] += r_ * psi;
      x_out[1] += h_ * psi;
      for (unsigned j = 0; j < n_dim; j++) {
        const double u_ = this->nodal_value(l, u_index[j]);
        const double w_ = this->dnodal_position_dt(l, j);
        u_out[j] += u_ * psi;
        dx_dt_out[j]+=w_ * psi;
      }
    }

    this->outer_unit_normal(s, n_out);
  }

  /// Overload the output function in .cc file
  void output(std::ostream &outfile) { FiniteElement::output(outfile); }

  /// Overload the output function
  void output(std::ostream &outfile, const unsigned &n_plot);

  /// Overload the C-style output function
  void output(FILE *file_pt) { FiniteElement::output(file_pt); }

  /// C-style Output function
  void output(FILE *file_pt, const unsigned &n_plot) {
    FiniteElement::output(file_pt, n_plot);
  }

}; // End of Vapour Class

/// =============================================================================
/// This is the policy class for the Interface Lubrication equations which
/// require one additional value for the surface concentration
//=============================================================================
template <>
class FluidInterfaceAdditionalValues<LowerInterfaceLubricationElement> {
public:
  FluidInterfaceAdditionalValues<LowerInterfaceLubricationElement>() {}

  inline unsigned nadditional_values(const unsigned &n) { return 1; }

  inline void
  setup_equation_indices(LowerInterfaceLubricationElement *const &element_pt,
                         const unsigned &id) {
    const unsigned n_node = element_pt->nnode();
    Vector<unsigned> al_index(n_node);
    for (unsigned n = 0; n < n_node; n++) {
      al_index[n] = dynamic_cast<BoundaryNodeBase *>(element_pt->node_pt(n))
                        ->index_of_first_value_assigned_by_face_element(id);
    }

    element_pt->set_al_index(al_index);
  }
};

/// Specialise to the Axisymmetric geometry
template <class ELEMENT>
class ElasticAxisymmetricLowerInterfaceLubricationElement
    : public ElasticUpdateFluidInterfaceElement<
          LowerInterfaceLubricationElement, AxisymmetricDerivatives, ELEMENT> {
public:
  ElasticAxisymmetricLowerInterfaceLubricationElement(
      FiniteElement *const &element_pt, const int &face_index)
      : ElasticUpdateFluidInterfaceElement<LowerInterfaceLubricationElement,
                                           AxisymmetricDerivatives, ELEMENT>(
            element_pt, face_index) {}
};

// Define the bounding element type for the axisymmetric surface
template <class ELEMENT>
class BoundingElementType<ElasticUpdateFluidInterfaceElement<
    LowerInterfaceLubricationElement, AxisymmetricDerivatives, ELEMENT>>
    : public ElasticPointFluidInterfaceBoundingElement<ELEMENT> {
public:
  BoundingElementType<ElasticUpdateFluidInterfaceElement<
      LowerInterfaceLubricationElement, AxisymmetricDerivatives, ELEMENT>>()
      : ElasticPointFluidInterfaceBoundingElement<ELEMENT>() {}
};

} // namespace oomph

#endif
